import java.util.*;

class ParkingSystemBrute {
    Map<Integer, Integer> capacity = new HashMap<>();
    Map<Integer, List<Boolean>> parked = new HashMap<>();

    ParkingSystemBrute(int big, int medium, int small) {
        capacity.put(1, big); capacity.put(2, medium); capacity.put(3, small);
        parked.put(1, new ArrayList<>()); parked.put(2, new ArrayList<>()); parked.put(3, new ArrayList<>());
    }

    boolean addCar(int carType) {
        if (parked.get(carType).size() < capacity.get(carType)) {
            parked.get(carType).add(true);               // just a placeholder entry
            return true;
        }
        return false;
    }
}

